namespace IAM.Core.Security;

/// <summary>
/// The one rule for a password a person chooses (register, reset, invitation, admin and portal change).
/// Passwords generated by the system (SCIM, LDAP, social, bulk import) do not go through it.
/// </summary>
public static class PasswordPolicy
{
    public const int MinLength = 8;

    public static readonly string TooShortMessage = $"Password must be at least {MinLength} characters";

    public static bool IsValid(string? password) => password != null && password.Length >= MinLength;

    /// <summary>Null when the password is acceptable, otherwise the message to show.</summary>
    public static string? Validate(string? password) => IsValid(password) ? null : TooShortMessage;
}
